const targetOrigin = process.env.ADDIN_URL;

/**
 * Shows a notification when the add-in command is executed.
 * @param event
 */
function action(event: Office.AddinCommands.Event) {
  const message: Office.NotificationMessageDetails = {
    type: Office.MailboxEnums.ItemNotificationMessageType.InformationalMessage,
    message: "Performed action.",
    icon: "Icon.80x80",
    persistent: true,
  };

  // Show a notification message.
  Office.context.mailbox.item?.notificationMessages.replaceAsync(
    "ActionPerformanceNotification",
    message
  );

  // Be sure to indicate when the add-in command function is complete.
  event.completed();
}

type SafeRecipientsChangedEvent = Office.RecipientsChangedEventArgs & Office.MailboxEvent & {
  // Keep your debugging fallback fields from earlier
  to?: boolean;
  cc?: boolean;
  bcc?: boolean;
};


async function onMessageRecipientsChangedHandler(event: SafeRecipientsChangedEvent): Promise<void> {
  // Send a message to the task pane when the recipients change.

  // Office.context.mailbox.item?.subject.getAsync((asyncResult) => {
  //   if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
  //     // The subject string is stored in the value property
  //     const subject = asyncResult.value;
  //     console.log("The current subject is: " + subject);
  //   } else {
  //     // Handle potential execution errors
  //     console.error("Failed to read subject: " + JSON.stringify(asyncResult.error));
  //   }
  // });


  if (!event) return;

  try {
    const safeEvent = event as SafeRecipientsChangedEvent;
    const mailItem = Office.context.mailbox.item;

    if (mailItem == null) {
      return;
    }
    else if (mailItem.itemType !== Office.MailboxEnums.ItemType.Message) {
      return;
    }

    const targetDomain = "@inmailx.onmicrosoft.com";
    let hasExternalRecipient = false;

    // 1. Identify which fields changed using our safe runtime checks
    const checkTo = safeEvent.changedRecipientFields ? safeEvent.changedRecipientFields.to : !!safeEvent.to;
    const checkCc = safeEvent.changedRecipientFields ? safeEvent.changedRecipientFields.cc : !!safeEvent.cc;
    const checkBcc = safeEvent.changedRecipientFields ? safeEvent.changedRecipientFields.bcc : !!safeEvent.bcc;

    // 2. Clear any existing warning notifications before re-validating
    mailItem.notificationMessages.replaceAsync("ExternalDomainWarning", {
      type: Office.MailboxEnums.ItemNotificationMessageType.ProgressIndicator,
      message: "Validating recipients..."
    });

    // 3. Inspect recipients across fields that changed
    if (checkTo) {
      const toRecipients = await getRecipientsAsync(mailItem.to);
      if (hasInvalidDomain(toRecipients, targetDomain)) hasExternalRecipient = true;
    }
    if (!hasExternalRecipient && checkCc) {
      const ccRecipients = await getRecipientsAsync(mailItem.cc);
      if (hasInvalidDomain(ccRecipients, targetDomain)) hasExternalRecipient = true;
    }
    if (!hasExternalRecipient && checkBcc) {
      const bccRecipients = await getRecipientsAsync(mailItem.bcc);
      if (hasInvalidDomain(bccRecipients, targetDomain)) hasExternalRecipient = true;
    }

    // 4. Update the Outlook notification UI based on evaluation results
    if (hasExternalRecipient) {
      mailItem.notificationMessages.replaceAsync("ExternalDomainWarning", {
        type: Office.MailboxEnums.ItemNotificationMessageType.ErrorMessage,
        message: "Warning: One or more recipients do not belong to inmailx.onmicrosoft.com."
      });
    } else {
      // Remove the notification banner if all domains match
      mailItem.notificationMessages.removeAsync("ExternalDomainWarning");
    }

  } catch (error) {
    console.error("Error processing recipient validation:", error);
  } finally {
    // 5. Always signal completion so the client event loop finishes smoothly
    if (event && typeof event.completed === "function") {
      event.completed();
    }
  }

}
function getRecipientsAsync(recipientField: Office.Recipients): Promise<Office.EmailAddressDetails[]> {
  return new Promise((resolve, reject) => {
    recipientField.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value);
      } else {
        reject(result.error);
      }
    });
  });
}

function hasInvalidDomain(recipients: Office.EmailAddressDetails[], allowedDomain: string): boolean {
  return recipients.some(recipient => {
    const email = recipient.emailAddress ? recipient.emailAddress.toLowerCase().trim() : "";
    // Flags true if an address is populated but doesn't end with the requested domain
    return email.length > 0 && !email.endsWith(allowedDomain.toLowerCase());
  });
}

